### 6. TieredLoadingCache 사용 패턴

#### 6.1 CategoryApplicationService (proxy)

**파일:** `/Users/admin/project/integrated-search/application/index/src/main/kotlin/com/cowave/search/application/index/service/proxy/CategoryApplicationService.kt`

```kotlin
@Service
class CategoryApplicationService(
    private val categoryProxyReader: CategoryProxyReader,
    private val categoryRepository: CategoryRepository,
    categoryGlobalCache: GlobalCache<Int, CategoryProjection>,  // 주입받음
    localCacheProperties: LocalCacheProperties,
) {
    private val localCache =
        LocalCacheFactory.create<Int, CategoryProjection>(
            keyPrefix = LOCAL_CACHE_KEY_PREFIX,
            ttlSeconds = localCacheProperties.brand.ttlSeconds,
        )

    private val tieredCache =
        TieredLoadingCacheFactory.create(
            localCache = localCache,
            globalCache = categoryGlobalCache,  // CategoryRepositoryImpl 주입됨
            fetcher = { ids -> 
                categoryProxyReader.getAllByIds(ids.toList())
                    .associateBy { it.id }  // L3: 실제 데이터 조회
            },
        )

    fun getCachedAllByIds(ids: List<Int>): Map<Int, CategoryProjection> =
        tieredCache.getAll(ids)
            .filterValues { it != null }
            .mapValues { it.value!! }
}
```

**LocalCacheProperties 설정:**

```kotlin
@ConfigurationProperties(prefix = "local-cache")
data class LocalCacheProperties(
    val mall: LocalCacheProperty = LocalCacheProperty(ttlSeconds = 600L),    // 10분
    val category: LocalCacheProperty = LocalCacheProperty(ttlSeconds = 600L),  // 10분
    val brand: LocalCacheProperty = LocalCacheProperty(ttlSeconds = 3600L),   // 1시간
    val manufacturer: LocalCacheProperty = LocalCacheProperty(ttlSeconds = 3600L),  // 1시간
