#### 7.3 AbstractValkeyRepository (공통 구현)

**파일:** `/Users/admin/project/integrated-search/outbound/repository/cache/src/main/kotlin/com/cowave/search/repository/cache/AbstractValkeyRepository.kt`

```kotlin
abstract class AbstractValkeyRepository<ID, V : Any>(
    private val redisTemplate: RedisTemplate<String, String>,
    private val serializer: KSerializer<V>,
    private val keyPrefix: String,
) {
    protected fun hashMultiGet(ids: List<ID>): List<V?> {
        return redisTemplate.opsForHash<String, String>()
            .multiGet(getHashKey(), ids.toFields())
            .map { it?.let(::deserialize) }  // null 포함하여 반환
    }

    protected fun hashMultiSet(keyValuePairs: Map<ID, V>) {
        return redisTemplate.opsForHash<String, String>()
            .putAll(
                getHashKey(),
                keyValuePairs.map { (k, v) ->
                    k.toField() to serialize(v)
                }.toMap()
            )
    }

    private fun serialize(value: V): String = 
        defaultJson.encodeToString(serializer, value)

    private fun deserialize(jsonString: String): V = 
        defaultJson.decodeFromString(serializer, jsonString)

    protected fun getHashKey(): String = keyPrefix
    protected fun ID.toField(): String = this.toString()
    protected fun List<ID>.toFields(): List<String> = 
        this.map { it.toField() }
}
```

